ht:245px;background-image:linear-gradient(rgba(10,58,84,.24),rgba(10,58,84,.24)),url('/al_bg.png')}.news-body{padding:20px}.news-body time{color:var(--green);font-size:12px;font-weight:900}.news-body h3{margin:6px 0;color:var(--navy);font-size:19px;line-height:1.5}.news-body p{margin:0;color:var(--muted);font-size:13px}.contact-grid{display:grid;grid-template-columns:1fr .95fr;gap:45px;align-items:start}.contact-cards{display:grid;gap:12px;margin-top:25px}.contact-item{display:flex;align-items:center;gap:14px;padding:15px;border:1px solid var(--line);border-radius:8px;background:#fff}.contact-item i{display:grid;flex:0 0 39px;width:39px;height:39px;place-items:center;border-radius:50%;color:var(--green);background:var(--mint);font-style:normal}.contact-item strong,.contact-item span{display:block}.contact-item span{color:var(--muted);font-size:13px}.portal-box{padding:32px;border-radius:10px;color:#fff;background:var(--green)}.portal-box h3{margin-top:0;font-size:25px}.portal-box p{color:#dcfff4}.portal-links{display:grid;gap:10px;margin-top:22px}.portal-links a{display:flex;justify-content:space-between;padding:12px 15px;border-radius:6px;background:rgba(255,255,255,.13);font-weight:800}.footer{padding:30px 0;color:#b9cbd8;background:#072741;font-size:13px}.footer .container{display:flex;align-items:center;justify-content:space-between;gap:18px}.footer strong{color:#fff;font-size:16px}@media(max-width:850px){.topline{display:none}.nav{min-height:70px}.menu{display:block}.navlinks{position:absolute;top:70px;right:0;left:0;display:none;flex-direction:column;align-items:stretch;gap:0;padding:10px 20px 20px;background:#fff;border-top:1px solid var(--line)}.navlinks.open{display:flex}.navlinks a{padding:10px 0}.navlinks .button{margin-top:8px}.quick-grid,.cards{grid-template-columns:repeat(2,1fr)}.about,.admission-inner,.contact-grid{grid-template-columns:1fr}.about-image{min-height:300px;order:2}.news{grid-template-columns:1fr 1fr}.news-card:first-child{grid-row:auto;g